.hero-cta { display: inline-flex; align-items: center; gap: 6px; font-size: 17px; color: #0066cc; font-weight: 400; }
.hero-cta svg { width: 11px; height: 11px; fill: #0066cc; }
@media (max-width: 734px) {
  .hero-section h1 { font-size: 36px; }
  .hero-section .subtitle { font-size: 19px; }
}

/* ===== PRODUCT GRID (HOMEPAGE) ===== */
.product-grid {
  max-width: 1200px; margin: 0 auto; padding: 0 22px;
  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
}
.product-tile {
  border-radius: 24px; overflow: hidden;
  text-align: center; padding: 44px 30px 0;
  min-height: 520px; display: flex; flex-direction: column;
  align-items: center; position: relative;
}
.product-tile.dark { background: #1d1d1f; color: #f5f5f7; }
.product-tile.dark a { color: #2997ff; }
.product-tile.light { background: #f5f5f7; color: #1d1d1f; }
.product-tile.gradient-warm { background: linear-gradient(180deg, #fbfbfd 0%, #f0e8dc 100%); color: #1d1d1f; }
.product-tile.gradient-cool { background: linear-gradient(180deg, #f5f5f7 0%, #e8eaf0 100%); color: #1d1d1f; }
.product-tile h2 { font-size: 40px; font-weight: 700; letter-spacing: -0.01em; }
.product-tile .tagline { font-size: 21px; font-weight: 400; color: inherit; opacity: 0.8; margin-top: 4px; }
.product-tile .tile-ctas { display: flex; gap: 20px; margin-top: 14px; }
.product-tile .tile-ctas a { font-size: 17px; font-weight: 400; }
.product-tile .tile-image { flex: 1; width: 100%; display: flex; align-items: flex-end; justify-content: center; margin-top: 20px; }
.product-tile .tile-image .placeholder-img {
  width: 70%; height: 260px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 48px; opacity: 0.25;
}
@media (max-width: 734px) {
  .product-grid { grid-template-columns: 1fr; }
  .product-tile { min-height: 420px; }
  .product-tile h2 { font-size: 32px; }
  .product-tile .tagline { font-size: 17px; }
}

/* ===== CAROUSEL ===== */
.carousel-section { padding: 60px 0; }
.carousel-header {
  max-width: 1200px; margin: 0 auto; padding: 0 22px 20px;
}
.carousel-header .section-headline { font-size: 40px; }
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex; gap: 16px;
  overflow-x: auto; scroll-behavior: smooth;
  padding: 0 22px 20px;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-arrow {
  position: absolute; top: 50%; transform: translateY(-70%);
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255,255,255,0.9); border: 1px solid #d2d2d7;
  display: flex; align-items: center; justify-content: center;
  z-index: 10; box-shadow: 0 2px 8px rgba(0,0,0,0.08);
  transition: opacity 0.2s;
}
.carousel-arrow:hover { background: #fff; }
.carousel-arrow.left { left: 8px; }
.carousel-arrow.right { right: 8px; }
.carousel-arrow svg { width: 16px; height: 16px; fill: #1d1d1f; }
.carousel-arrow:disabled { opacity: 0; pointer-events: none; }

/* ===== PRODUCT CARD ===== */
.product-card {
  flex: 0 0 280px; border-radius: 20px; overflow: hidden;
  background: #f5f5f7; display: flex; flex-direction: column;
}
.product-card .card-image {
  height: 220px; display: flex; align-items: center; justify-content: center;
  position: relative;
}
.product-card .card-image .placeholder-img {
  width: 60%; height: 160px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 36px; opacity: 0.3;
}
.product-card .card-badge {
  position: absolute; top: 14px; left: 14px;
  background: #bf4800; color: #fff; font-size: 11px; font-weight: 600;
  padding: 2px 8px; border-radius: 4px; text-transform: uppercase;
}
.product-card .card-body { padding: 16px 18px 20px; }
.product-card .card-name { font-size: 17px; font-weight: 600; line-height: 1.3; }
.product-card .card-tagline { font-size: 14px; color: #6e6e73; margin-top: 4px; line-height: 1.4; }
.product-card .card-price { font-size: 14px; margin-top: 8px; }
.product-card .card-monthly { font-size: 12px; color: #6e6e73; margin-top: 2px; }
.product-card .card-ctas { margin-top: 10px; display: flex; gap: 14px; }
.product-card .card-ctas a { font-size: 14px; }

/* ===== ACCESSORY CARD ===== */
.accessory-card {
  flex: 0 0 200px; border-radius: 20px; overflow: hidden;
  background: #f5f5f7; display: flex; flex-direction: column;
  align-items: center; padding-top: 24px;
}
.accessory-card .card-image { width: 120px; height: 120px; display: flex; align-items: center; justify-content: center; }
.accessory-card .card-image .placeholder-img {
  width: 100%; height: 100%; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 28px; opacity: 0.3;
}
.accessory-card .card-body { padding: 12px 16px 18px; text-align: center; }
.accessory-card .card-name { font-size: 14px; font-weight: 600; line-height: 1.35; }
.accessory-card .card-price { font-size: 14px; margin-top: 6px; }

/* ===== AUDIO CARD ===== */
.audio-card {
  flex: 0 0 240px; border-radius: 20px; overflow: hidden;
  background: #1d1d1f; color: #f5f5f7; display: flex; flex-direction: column;
}
.audio-card .card-image {
  height: 200px; display: flex; align-items: center; justify-content: center;
}
.audio-card .card-image .placeholder-img {
  width: 55%; height: 140px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 32px; opacity: 0.35;
}
.audio-card .card-body { padding: 14px 18px 20px; }
.audio-card .card-name { font-size: 16px; font-weight: 600; color: #f5f5f7; }
.audio-card .card-note { font-size: 12px; color: #86868b; margin-top: 2px; }
.audio-card .card-price { font-size: 14px; margin-top: 6px; color: #f5f5f7; }
.audio-card .card-ctas a { color: #2997ff; }

/* ===== HELP / DIFFERENCE CARD ===== */
.info-card {
  flex: 0 0 280px; border-radius: 24px; overflow: hidden;
  background: #f5f5f7; display: flex; flex-direction: column;
}
.info-card .card-icon {
  height: 180px; display: flex; align-items: center; justify-content: center;
}
.info-card .card-icon .icon-circle {
  width: 80px; height: 80px; border-radius: 50%;
  background: #e8e8ed; display: flex; align-items: center; justify-content: center;
  font-size: 32px;
}
.info-card .card-body { padding: 16px 20px 24px; }
.info-card .card-title { font-size: 20px; font-weight: 600; line-height: 1.25; }
.info-card .card-desc { font-size: 14px; color: #6e6e73; margin-top: 6px; line-height: 1.45; }
.info-card .card-ctas { margin-top: 10px; }
.info-card .card-ctas a { font-size: 14px; }

/* ===== PRODUCT ICON BAR ===== */
.product-icon-bar {
  background: #fff; border-bottom: 1px solid #d2d2d7;
  position: sticky; top: 44px; z-index: 90;
}
.product-icon-bar-inner {
  max-width: 1200px; margin: 0 auto;
  display: flex; justify-content: center; gap: 32px;
  padding: 12px 22px; overflow-x: auto;
  scrollbar-width: none;
}
.product-icon-bar-inner::-webkit-scrollbar { display: none; }
.product-icon-bar .icon-item {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  flex-shrink: 0;
}
.product-icon-bar .icon-item a { text-align: center; }
.product-icon-bar .icon-img {
  width: 48px; height: 48px; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  font-size: 22px; margin: 0 auto;
}
.product-icon-bar .icon-label { font-size: 11px; color: #1d1d1f; font-weight: 400; white-space: nowrap; }

/* ===== ENTERTAINMENT TABS ===== */
.entertainment-section { padding: 60px 22px; background: #fff; }
.entertainment-section .section-headline { text-align: center; }
.tab-nav {
  display: flex; justify-content: center; gap: 8px;
  margin: 24px auto 32px;
}
.tab-btn {
  padding: 8px 20px; border-radius: 20px;
  font-size: 14px; font-weight: 500; color: #1d1d1f;
  background: #e8e8ed; transition: all 0.2s;
}
.tab-btn.active { background: #1d1d1f; color: #fff; }
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.entertainment-grid {
  max-width: 1200px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px;
}
.entertainment-card {
  border-radius: 16px; overflow: hidden;
  background: #f5f5f7; aspect-ratio: 3/4;
  display: flex; flex-direction: column; justify-content: flex-end;
  padding: 18px; position: relative;
}
.entertainment-card .card-bg {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-size: 48px; opacity: 0.15;
}
.entertainment-card .card-title { font-size: 16px; font-weight: 600; position: relative; }
.entertainment-card .card-subtitle { font-size: 12px; color: #6e6e73; margin-top: 2px; position: relative; }
.entertainment-card .card-cta { font-size: 13px; margin-top: 8px; position: relative; }
@media (max-width: 734px) {
  .entertainment-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ===== CATEGORY HERO ===== */
.category-hero {
  text-align: center; padding: 60px 22px 40px;
  background: #f5f5f7;
}
.category-hero h1 { font-size: 56px; font-weight: 700; letter-spacing: -0.02em; }
.category-hero .subtitle { font-size: 21px; color: #6e6e73; margin-top: 6px; }

/* ===== STICKY SECTION NAV ===== */
.sticky-section-nav {
  position: sticky; top: 44px; z-index: 90;
  background: rgba(255,255,255,0.9);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid #d2d2d7;
}
.sticky-section-nav-inner {
  max-width: 1200px; margin: 0 auto;
  display: flex; gap: 0; padding: 0 22px; overflow-x: auto;
  scrollbar-width: none;
}
.sticky-section-nav-inner::-webkit-scrollbar { display: none; }
.sticky-section-nav a {
  padding: 12px 16px; font-size: 13px; color: #6e6e73;
  white-space: nowrap; border-bottom: 2px solid transparent;
  transition: all 0.2s;
}
.sticky-section-nav a:hover { text-decoration: none; color: #1d1d1f; }
.sticky-section-nav a.active { color: #1d1d1f; border-bottom-color: #1d1d1f; }

/* ===== CATEGORY SECTIONS ===== */
.category-section {
  padding: 60px 22px; max-width: 1200px; margin: 0 auto;
  scroll-margin-top: 90px;
}

/* ===== SHOPPING GUIDE / WAYS TO SAVE CARDS ===== */
.guide-card {
  background: #f5f5f7; border-radius: 20px; padding: 28px 24px;
}
.guide-card .card-title { font-size: 17px; font-weight: 600; }
.guide-card .card-desc { font-size: 14px; color: #6e6e73; margin-top: 4px; }
.guide-card .card-cta { margin-top: 10px; }
.guide-card .card-cta a { font-size: 14px; }
.guide-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 14px;
}

/* ===== BRAND COLLAB ===== */
.brand-collab-section {
  background: #1d1d1f; color: #f5f5f7;
  padding: 60px 22px; text-align: center;
}
.brand-collab-section .section-headline { color: #f5f5f7; }
.brand-collab-section .section-subheadline { color: #86868b; }

/* ===== QUICK LINKS ===== */
.quick-links-section { padding: 40px 22px; }
.quick-links-inner {
  max-width: 1200px; margin: 0 auto;
  display: flex; justify-content: center; gap: 28px; flex-wrap: wrap;
}
.quick-link {
  display: flex; align-items: center; gap: 6px;
  font-size: 14px; color: #0066cc;
}
.quick-link svg { width: 16px; height: 16px; fill: #0066cc; }

/* ===== FOOTER ===== */
.site-footer {
  background: #f5f5f7; padding: 20px 22px 30px;
  border-top: 1px solid #d2d2d7;
}
.footer-inner { max-width: 980px; margin: 0 auto; }
.footer-legal { font-size: 12px; color: #6e6e73; line-height: 1.55; padding-bottom: 16px; border-bottom: 1px solid #d2d2d7; }
.footer-nav-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 20px;
  padding: 20px 0 16px;
}
.footer-nav-col h4 {
  font-size: 12px; font-weight: 600; color: #1d1d1f;
  margin-bottom: 8px;
}
.footer-nav-col ul li { margin-bottom: 4px; }
.footer-nav-col ul li a { font-size: 12px; color: #6e6e73; }
.footer-nav-col ul li a:hover { color: #1d1d1f; text-decoration: none; }
.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  padding-top: 16px; border-top: 1px solid #d2d2d7;
}
.footer-bottom .locale { font-size: 12px; color: #6e6e73; }
.footer-bottom .legal-links { display: flex; gap: 16px; }
.footer-bottom .legal-links a { font-size: 12px; color: #6e6e73; }

/* Mobile footer accordion */
@media (max-width: 734px) {
  .footer-nav-grid {
    grid-template-columns: 1fr; gap: 0;
  }
  .footer-nav-col { border-bottom: 1px solid #d2d2d7; }
  .footer-nav-col h4 {
    padding: 12px 0; margin-bottom: 0;
    display: flex; justify-content: space-between; align-items: center;
    cursor: pointer; user-select: none;
  }
  .footer-nav-col h4::after {
    content: '+'; font-size: 16px; font-weight: 300; color: #6e6e73;
    transition: transform 0.2s;
  }
  .footer-nav-col.open h4::after { content: '−'; }
  .footer-nav-col ul {
    max-height: 0; overflow: hidden;
    transition: max-height 0.3s ease;
  }
  .footer-nav-col.open ul { max-height: 400px; }
  .footer-nav-col ul li { padding: 4px 0; }
  .footer-bottom { flex-direction: column; gap: 8px; align-items: flex-start; }
}

/* ===== SAVINGS CARD ===== */
.savings-card {
  flex: 0 0 280px; border-radius: 20px; overflow: hidden;
  background: #f5f5f7; padding: 28px 24px;
}
.savings-card .card-icon { font-size: 32px; margin-bottom: 12px; }
.savings-card .card-title { font-size: 20px; font-weight: 600; line-height: 1.25; }
.savings-card .card-desc { font-size: 14px; color: #6e6e73; margin-top: 6px; line-height: 1.45; }
.savings-card .card-cta { margin-top: 12px; }
.savings-card .card-cta a { font-size: 14px; }

/* ===== EXPERIENCE SECTION ===== */
.experience-section {
  text-align: center; padding: 60px 22px;
  background: #f5f5f7;
}
.experience-cards {
  max-width: 1200px; margin: 20px auto 0;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 14px;
}
.experience-card {
  background: #fff; border-radius: 20px; padding: 28px 24px;
  text-align: left;
}
.experience-card .card-icon { font-size: 28px; margin-bottom: 10px; }
.experience-card .card-title { font-size: 17px; font-weight: 600; }
.experience-card .card-desc { font-size: 14px; color: #6e6e73; margin-top: 4px; line-height: 1.45; }
.experience-card .card-cta { margin-top: 10px; }
.experience-card .card-cta a { font-size: 14px; }

/* ===== MODEL CARD (Category pages) ===== */
.model-card {
  flex: 0 0 300px; border-radius: 24px; overflow: hidden;
  background: #f5f5f7; display: flex; flex-direction: column; text-align: center;
}
.model-card .card-image {
  height: 200px; display: flex; align-items: center; justify-content: center;
  position: relative;
}
.model-card .card-image .placeholder-img {
  width: 65%; height: 140px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 40px; opacity: 0.3;
}
.model-card .card-badge {
  position: absolute; top: 14px; left: 14px;
  background: #bf4800; color: #fff; font-size: 11px; font-weight: 600;
  padding: 2px 8px; border-radius: 4px; text-transform: uppercase;
}
.model-card .card-body { padding: 16px 20px 24px; }
.model-card .card-name { font-size: 22px; font-weight: 700; }
.model-card .card-price { font-size: 17px; margin-top: 8px; }
.model-card .card-monthly { font-size: 13px; color: #6e6e73; margin-top: 2px; }
.model-card .card-ctas { margin-top: 12px; display: flex; gap: 16px; justify-content: center; }
.model-card .card-ctas a { font-size: 14px; }

/* ===== SETUP / SPECIAL STORES ===== */
.setup-section, .special-stores-section { padding: 60px 22px; max-width: 1200px; margin: 0 auto; }

/* ===== PLACEHOLDER IMAGE GRADIENTS ===== */
.img-phone { background: linear-gradient(135deg, #c9b8e8 0%, #8e7cc3 100%); }
.img-laptop { background: linear-gradient(135deg, #a8d8ea 0%, #6c9bcf 100%); }
.img-tablet { background: linear-gradient(135deg, #f6d6ad 0%, #d4a76a 100%); }
.img-watch { background: linear-gradient(135deg, #b8e6c8 0%, #5bae7c 100%); }
.img-headphones { background: linear-gradient(135deg, #e8c9b8 0%, #c08552 100%); }
.img-earbuds { background: linear-gradient(135deg, #f0d0d0 0%, #c97b7b 100%); }
.img-speaker { background: linear-gradient(135deg, #d4c9e8 0%, #8e6ec3 100%); }
.img-accessory { background: linear-gradient(135deg, #e0e0e0 0%, #b0b0b0 100%); }
.img-desktop { background: linear-gradient(135deg, #c0c0c0 0%, #808080 100%); }
.img-tradein { background: linear-gradient(135deg, #7ec8a0 0%, #3d9970 100%); }

